/**
 * Converts selected JSON Schema contracts into deterministic domain TypeScript
 * aliases, then formats the generated file with the repository configuration.
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { format, resolveConfig } from 'prettier';

const root = resolve(import.meta.dirname, '..');
const schemasDir = resolve(root, 'schemas/domain');
const outputFile = resolve(root, 'packages/domain/src/generated/schema-contracts.ts');

const refTypeMap = new Map([
  ['./_defs/common.schema.json#/$defs/id', 'string'],
  ['./_defs/common.schema.json#/$defs/dateTime', 'string'],
  ['./_defs/common.schema.json#/$defs/date', 'string'],
  ['./_defs/common.schema.json#/$defs/email', 'string'],
  ['./_defs/common.schema.json#/$defs/nonNegativeNumber', 'number'],
  ['./audit-entry.schema.json', 'Record<string, unknown>'],
]);

function indent(lines, depth) {
  const prefix = '  '.repeat(depth);
  return lines
    .split('\n')
    .map((line) => (line.length > 0 ? `${prefix}${line}` : line))
    .join('\n');
}

function enumType(values) {
  return values
    .map((value) =>
      typeof value === 'string' ? `'${value.replaceAll("'", "\\'")}'` : String(value),
    )
    .join(' | ');
}

function unionType(schema, depth) {
  return schema.type
    .map((typeValue) =>
      typeValue === 'null' ? 'null' : schemaToType({ ...schema, type: typeValue }, depth),
    )
    .join(' | ');
}

function scalarType(type) {
  if (type === 'string') return 'string';
  if (type === 'integer' || type === 'number') return 'number';
  if (type === 'boolean') return 'boolean';
  return null;
}

function arrayType(schema, depth) {
  const itemType = schemaToType(schema.items, depth);
  const needsParentheses = Array.isArray(schema.items?.type) || Boolean(schema.items?.enum);
  return `${needsParentheses ? `(${itemType})` : itemType}[]`;
}

function objectType(schema, depth) {
  const required = new Set(schema.required ?? []);
  const entries = Object.entries(schema.properties ?? {});
  if (entries.length === 0) {
    return schema.additionalProperties ? 'Record<string, unknown>' : '{}';
  }
  const lines = entries.map(([propertyName, propertySchema]) => {
    const optional = required.has(propertyName) ? '' : '?';
    return `${propertyName}${optional}: ${schemaToType(propertySchema, depth + 1)};`;
  });
  return ['{', indent(lines.join('\n'), 1), '}'].join('\n');
}

/** Maps the supported JSON Schema subset to a deterministic TypeScript type expression. */
export function schemaToType(schema, depth = 0) {
  if (!schema) return 'unknown';
  if (schema.$ref) return refTypeMap.get(schema.$ref) ?? 'Record<string, unknown>';
  if (schema.enum) return enumType(schema.enum);
  if (Array.isArray(schema.type)) return unionType(schema, depth);
  const scalar = scalarType(schema.type);
  if (scalar) return scalar;
  if (schema.type === 'array') return arrayType(schema, depth);
  if (schema.type === 'object') return objectType(schema, depth);
  return 'unknown';
}

/** Renders sorted schema contracts as a generated TypeScript declaration module. */
export function renderCoreSchemaTypes(schemas) {
  const declarations = schemas.map(({ file, schema }) => {
    if (!schema.title) throw new Error(`Schema ${file} has no title.`);
    return `export type ${schema.title} = ${schemaToType(schema)};`;
  });
  return [
    '// AUTO-GENERATED FILE. DO NOT HAND-EDIT.',
    '// Generated by scripts/generate-domain-schema-types.mjs.',
    '',
    ...declarations,
    '',
  ].join('\n');
}

async function main() {
  const files = (await readdir(schemasDir))
    .filter((file) => file.startsWith('core-') && file.endsWith('.schema.json'))
    .sort();

  const schemas = await Promise.all(
    files.map(async (file) => ({
      file,
      schema: JSON.parse(await readFile(resolve(schemasDir, file), 'utf8')),
    })),
  );
  const prettierConfig = (await resolveConfig(outputFile)) ?? {};
  const content = await format(renderCoreSchemaTypes(schemas), {
    ...prettierConfig,
    filepath: outputFile,
  });

  await writeFile(outputFile, content, 'utf8');
  console.log(`Generated ${outputFile}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => {
    console.error('Failed to generate domain schema types:', error);
    process.exit(1);
  });
}
